<script setup>
import {ref,onMounted,onBeforeUnmount} from 'vue';import gsap from 'gsap';import {ScrollTrigger} from 'gsap/ScrollTrigger';const root=ref(null),track=ref(null);let mm;const stages=[['01','Виртуализация','Ресурсы физической машины становятся независимыми виртуальными средами.','МАШИНА'],['02','Контейнеры','Приложение получает воспроизводимую упаковку вместе с зависимостями.','ПРОЦЕСС'],['03','Оркестрация','Платформа поддерживает желаемое состояние множества приложений.','КЛАСТЕР'],['04','Serverless','Код запускается в ответ на событие, управление серверами скрыто.','ФУНКЦИЯ'],['05','Edge','Обработка приближается к источнику данных и месту принятия решения.','ЛОКАЛЬНЫЙ УЗЕЛ']];onMounted(()=>{mm=gsap.matchMedia();mm.add('(min-width: 1100px) and (prefers-reduced-motion: no-preference)',()=>{gsap.to(track.value,{x:()=>-(track.value.scrollWidth-root.value.clientWidth),ease:'none',scrollTrigger:{trigger:root.value,start:'top 22%',end:()=>'+='+track.value.scrollWidth,pin:true,scrub:1,invalidateOnRefresh:true}})})});onBeforeUnmount(()=>mm?.revert())
</script><template><div ref="root" class="evolution"><p class="eyebrow">ЭВОЛЮЦИЯ ОБЛАЧНЫХ ТЕХНОЛОГИЙ</p><div ref="track" class="evolution-track"><article class="evolution-card" v-for="[n,title,text,unit] in stages"><span class="evolution-num">{{n}}</span><div class="evolution-glyph" aria-hidden="true"><i></i><i></i><i></i></div><small>{{unit}}</small><h3>{{title}}</h3><p>{{text}}</p></article></div></div></template>
